products = {7: 19.99}

# SELECT INTO with a NO_DATA_FOUND handler
try:
    v_price = products[7]
    print('price: ' + str(v_price))
except KeyError:
    print('caught NO_DATA_FOUND: id 7 missing, using 0')

try:
    v_missing = products[99]
    print('price: ' + str(v_missing))
except KeyError:
    print('caught NO_DATA_FOUND: id 99 missing, using 0')

class BadDiscount(Exception):
    pass  # DECLARE e_bad_discount EXCEPTION

def place_order(order_id, discount_pct):
    if discount_pct > 90:
        raise BadDiscount('discount too deep')  # RAISE e_bad_discount
    print(f'order placed: {order_id}')

for oid, pct in [(1001, 10), (1002, 95)]:
    try:
        place_order(oid, pct)
    except BadDiscount:
        print(f'rejected: discount {pct}% exceeds the 90% limit')

class AppError(Exception):
    def __init__(self, code, message):
        self.code = code
        self.message = message
        super().__init__(f'[Errno {code}] {message}')

def withdraw(balance, amount):
    if balance - amount < 0:
        # RAISE_APPLICATION_ERROR(-20001, 'Balance cannot go negative')
        raise AppError(-20001, 'Balance cannot go negative')
    return balance - amount

def safe_withdraw(balance, amount):
    try:
        return withdraw(balance, amount)
    except AppError as e:
        print('logged: ' + str(e))  # SQLCODE + SQLERRM, logged
        raise  # re-raise: the caller still sees it

# the caller receives the re-raised error
try:
    safe_withdraw(50, 100)
except AppError as e:
    print('caller got: ' + str(e))
